from pathlib import Path
import json,hashlib
r=Path(__file__).resolve().parent.parent
base=json.loads((r/'verification_regression_R10_on_R11.json').read_text());assert base['total_fresh_simulation_runs']==126
names=['irq_r11','irq_unit_r11','return_guard_r11','no_diag_r11','timing_platform','timing_legacy','cdc_r11_4','exsp_work_r11_2','msx_request_r11_3','slot_r11_4']
parts={n:json.loads((r/('verification_'+n+'_result.json')).read_text()) for n in names};counts={n:j.get('fresh_runs',j.get('runs',0)) for n,j in parts.items()}
assert counts==dict(irq_r11=41,irq_unit_r11=18,return_guard_r11=17,no_diag_r11=4,timing_platform=3,timing_legacy=4,cdc_r11_4=9,exsp_work_r11_2=12,msx_request_r11_3=2,slot_r11_4=0),counts
paths=[p for p in (r/'fpga').rglob('*') if p.is_file()]+list((r/'hardware_test').glob('*.COM'))
j=dict(series='restart R11.4B',purpose='SDRAM falling samples and rising transaction registers; R11.3 MSX request path retained for one-variable comparison',major_function_stage=7,timing_work_stage=10,R10_compatible_regression_runs=126,new_runs=counts,total_fresh_simulation_runs=126+sum(counts.values()),expected_failure_runs=base['expected_failure_runs']+parts['cdc_r11_4']['expected_failure_runs']+parts['msx_request_r11_3']['expected_failure_runs']+parts['slot_r11_4']['expected_failure_runs'],all_cases_executed_this_revision=True,verification_scope='CPU/bridge/controller regression, request-register unit tests and isolated platform tests; full top not simulated',PC_bits=24,SPS_bits=16,SPL_bits=24,I_bits=16,ADL_reset=0,preloaded_20_COM_unchanged=True,registered_MSX_address_and_window=True,full_CPU_SDRAM_fixtures_with_MSX_isolation_assertions=15,opcode_class_bits=16,SDRAM_payload_capture_edge='unconditional falling sample then rising transaction register',SDRAM_minimum_capture_receiver_cycles=3,SDRAM_minimum_sample_receiver_cycles=2.5,SDRAM_pending_minimum_receiver_cycles=3,SDRAM_payload_stable_until_ack_verified=True,SDC_byte_identical_to_R11_2=True,native_ADL_IM1_IM2_NMI_RETI_RETN=True,MBASE_MADL_mixed_frames_implemented=False,R11_2_user_report=json.loads((r/'doc/R11_2_GOWIN_BASELINE.json').read_text()),GOWIN_run_for_this_revision=False,hardware_run_for_this_revision=False,timing_closure_for_this_revision=False,area_for_this_revision_measured=False,PR1014_resolution_unverified=True,full_MSX_DOS_BIOS_simulated=False,sha256={str(p.relative_to(r)):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths})
assert j['total_fresh_simulation_runs']==236 and j['expected_failure_runs']==10
j['hardware_R11_3_failure']={'stage':'1','address':'07FFFF','expected':'52','actual':'D6','cause_not_proven':True}
j['monitor_fault_injection_is_not_hardware_failure_reproduction']=True
(r/'verification_result.json').write_text(json.dumps(j,indent=2)+'\n');print('PASS R11.4B aggregate 236 positive scenarios + 10 expected failures')
